(29, 413, 252, 'sentence_arrangement', '彼は休む（　　）（　　）（　　）働き続けた。', NULL, 'ことなく: Mà không…, chẳng hề…\r\n→ 休むことなく働き続けた。\r\n→ Anh ấy làm việc liên tục không nghỉ.', 'N2', 1, '2025-12-17 11:05:24'),
(30, 414, 253, 'sentence_arrangement', '（　　）（　　）（　　）、試験に落ちてしまった。', NULL, 'ことに: Thật là…, đặc biệt là (cảm xúc mạnh)\r\n→ 残念なことに…\r\n→ Thật đáng tiếc là tôi đã trượt kỳ thi.', 'N2', 1, '2025-12-17 11:05:24'),
(31, 415, 254, 'sentence_arrangement', '出発の（　　）（　　）（　　）、もう一度確認してください。', NULL, '際に: Khi…, vào lúc… (trang trọng)\r\n→ 出発の際に…\r\n→ Khi xuất phát, hãy kiểm tra lại.', 'N2', 1, '2025-12-17 11:05:24'),
(32, 416, 255, 'sentence_arrangement', '準備ができ（　　）（　　）（　　）、ご連絡します。', NULL, '次第: Ngay sau khi…\r\n→ 準備ができ次第…\r\n→ Ngay sau khi chuẩn bị xong sẽ liên lạc.', 'N2', 1, '2025-12-17 11:05:24'),
(33, 420, 256, 'sentence_arrangement', '悩んだ（　　）（　　）（　　）、会社を辞めることにした。', NULL, '末に: sau khi…, sau một quá trình dài\r\n→ 悩んだ末に\r\n→ Sau khi trăn trở một thời gian, tôi quyết định nghỉ việc.', 'N2', 1, '2025-12-17 11:12:01'),
(34, 421, 257, 'sentence_arrangement', '失敗の原因は努力不足（　　）（　　）（　　）。', NULL, 'にほかならない: không gì khác ngoài…, chính là…\r\n→ 努力不足にほかならない\r\n→ Nguyên nhân thất bại chính là do thiếu nỗ lực.', 'N2', 1, '2025-12-17 11:12:01'),
(35, 240, 240, 'multiple_choice', '3日間（　）雨が続いた。', NULL, 'trải suốt…', 'N3', 1, '2025-12-15 17:26:11'),
(36, 422, 258, 'sentence_arrangement', 'その話を聞いて、驚か（　　）（　　）（　　）。', NULL, 'ずにはいられない: không thể không…\r\n→ 驚かずにはいられない\r\n→ Nghe chuyện đó xong, tôi không thể không ngạc nhiên.', 'N2', 1, '2025-12-17 11:12:01'),
(37, 93, 93, 'multiple_choice', '雨が降れ（　）、行きません。', NULL, 'Thể điều kiện', 'N4', 1, '2025-12-15 17:05:39'),
